1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eef0f3;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 300px;
20	    padding: 16px;
21	    background: #1f2329;
22	    border-radius: 16px;
23	    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
24	  }
25	  .display {
26	    height: 72px;
27	    margin-bottom: 12px;
28	    padding: 0 12px;
29	    display: flex;
30	    align-items: center;
31	    justify-content: flex-end;
32	    background: #111418;
33	    color: #fff;
34	    font-size: 40px;
35	    border-radius: 10px;
36	    overflow: hidden;
37	    white-space: nowrap;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 8px;
43	  }
44	  button {
45	    height: 56px;
46	    border: 0;
47	    border-radius: 10px;
48	    background: #3a3f47;
49	    color: #fff;
50	    font-size: 22px;
51	    cursor: pointer;
52	  }
53	  button:active { filter: brightness(1.3); }
54	  button.op { background: #f0a030; }
55	  button.clear { background: #a5a5a5; color: #111; }
56	  button.equals { background: #3c8cf0; }
57	  button.wide { grid-column: span 2; }
58	</style>
59	</head>
60	<body>
61	<div class="calc">
62	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
63	  <div class="keys">
64	    <button class="clear wide" data-testid="key-clear">AC</button>
65	    <button class="op" data-testid="key-div" aria-label="divide">÷</button>
66	    <button class="op" data-testid="key-mul" aria-label="multiply">×</button>
67	
68	    <button data-testid="key-7">7</button>
69	    <button data-testid="key-8">8</button>
70	    <button data-testid="key-9">9</button>
71	    <button class="op" data-testid="key-sub" aria-label="subtract">−</button>
72	
73	    <button data-testid="key-4">4</button>
74	    <button data-testid="key-5">5</button>
75	    <button data-testid="key-6">6</button>
76	    <button class="op" data-testid="key-add" aria-label="add">+</button>
77	
78	    <button data-testid="key-1">1</button>
79	    <button data-testid="key-2">2</button>
80	    <button data-testid="key-3">3</button>
81	    <button class="equals" data-testid="key-equals" aria-label="equals">=</button>
82	
83	    <button class="wide" data-testid="key-0">0</button>
84	    <button data-testid="key-dot" aria-label="decimal point">.</button>
85	  </div>
86	</div>
87	<script>
88	(function () {
89	  var display = document.querySelector('[data-testid="calc-display"]');
90	
91	  // entry: string being typed, or null when no entry is in progress.
92	  // value: the number currently shown when not typing (result or stored operand).
93	  var state;
94	
95	  // [REQ-001]
96	  function reset() {
97	    state = { entry: null, value: 0, stored: null, op: null, error: false };
98	  }
99	
100	  // [REQ-001]
101	  function compute(a, op, b) {
102	    var r;
103	    if (op === 'add') r = a + b;
104	    else if (op === 'sub') r = a - b;
105	    else if (op === 'mul') r = a * b;
106	    else if (op === 'div') r = a / b;
107	    // [REQ-003] Division by zero (or any non-finite result) becomes the error state.
108	    // The result is never rounded here: rounding is presentation only.
109	    if (!isFinite(r)) return NaN;
110	    return r;
111	  }
112	
113	  // [REQ-003]
114	  // Presentation only: at most 10 significant digits, no trailing zeros, no
115	  // thousands separators, exponential only for |n| >= 1e10 or |n| < 1e-9.
116	  function formatNumber(n) {
117	    if (n === 0) return '0';
118	    var r = Number(n.toPrecision(10));
119	    var abs = Math.abs(r);
120	    if (abs >= 1e10 || abs < 1e-9) {
121	      return r.toExponential(9).replace(/\.?0+e/, 'e');
122	    }
123	    var exp = parseInt(r.toExponential().split('e')[1], 10);
124	    var s = r.toFixed(Math.max(0, 9 - exp));
125	    return s.indexOf('.') === -1 ? s : s.replace(/\.?0+$/, '');
126	  }
127	
128	  // [REQ-001] [REQ-003]
129	  function render() {
130	    display.setAttribute('data-error', state.error ? 'true' : 'false');
131	    if (state.error) {
132	      display.textContent = 'Error';
133	      display.setAttribute('data-value', String(NaN));
134	      return;
135	    }
136	    if (state.entry !== null) {
137	      display.textContent = state.entry;
138	      display.setAttribute('data-value', String(Number(state.entry)));
139	    } else {
140	      display.textContent = formatNumber(state.value);
141	      display.setAttribute('data-value', String(state.value));
142	    }
143	  }
144	
145	  // [REQ-001]
146	  function inputDigit(d) {
147	    if (state.entry === null || state.entry === '0') state.entry = d;
148	    else state.entry += d;
149	  }
150	
151	  // [REQ-001]
152	  function inputDot() {
153	    if (state.entry === null) state.entry = '0.';
154	    else if (state.entry.indexOf('.') === -1) state.entry += '.';
155	  }
156	
157	  // [REQ-001] [REQ-002]
158	  // Immediate execution: an operator key first finishes the waiting operation,
159	  // strictly left to right, with no precedence, so the display always shows a
160	  // real running result. 2 + 3 × 4 = 20.
161	  function inputOperator(op) {
162	    if (state.error) return;
163	    if (state.entry !== null) {
164	      var n = Number(state.entry);
165	      state.entry = null;
166	      if (state.op !== null && state.stored !== null) {
167	        state.value = compute(state.stored, state.op, n);
168	        if (isNaN(state.value)) { state.error = true; return; }
169	      } else {
170	        state.value = n;
171	      }
172	    }
173	    state.stored = state.value;
174	    state.op = op;
175	  }
176	
177	  // [REQ-001]
178	  function inputEquals() {
179	    if (state.error || state.op === null || state.entry === null) return;
180	    var result = compute(state.stored, state.op, Number(state.entry));
181	    state.entry = null;
182	    state.op = null;
183	    state.stored = null;
184	    if (isNaN(result)) { state.error = true; return; }
185	    state.value = result;
186	  }
187	
188	  // [REQ-001] [REQ-003]
189	  function press(key) {
190	    // In the error state every key except clear is ignored.
191	    if (state.error && key !== 'clear') return;
192	    if (/^[0-9]$/.test(key)) inputDigit(key);
193	    else if (key === 'dot') inputDot();
194	    else if (key === 'add' || key === 'sub' || key === 'mul' || key === 'div') inputOperator(key);
195	    else if (key === 'equals') inputEquals();
196	    else if (key === 'clear') reset();
197	    render();
198	  }
199	
200	  document.querySelector('.keys').addEventListener('click', function (e) {
201	    var btn = e.target.closest('button[data-testid^="key-"]');
202	    if (btn) press(btn.getAttribute('data-testid').slice(4));
203	  });
204	
205	  var keyMap = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul',
206	    '/': 'div', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
207	  document.addEventListener('keydown', function (e) {
208	    if (e.metaKey || e.ctrlKey || e.altKey) return;
209	    var key = /^[0-9]$/.test(e.key) ? e.key : keyMap[e.key];
210	    if (key) {
211	      e.preventDefault();
212	      press(key);
213	    }
214	  });
215	
216	  reset();
217	  render();
218	})();
219	</script>
220	</body>
221	</html>
